import{_ as r,a0 as l,w as p,s as a,ao as d,I as o,x as n,a1 as i,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux 服务器管理员的12个有用的命令 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 服务器管理员的12个有用的命令 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 服务器管理员的12个有用的命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 服务器管理员的12个有用的命令 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/12 Advanced Commands For Linux Server Admins!","title":"Linux 服务器管理员的12个有用的命令","tag":"201401","desc":""},"relativePath":"201401/12 Advanced Commands For Linux Server Admins!.md","filePath":"[post].md"}'),m={name:"201401/12 Advanced Commands For Linux Server Admins!.md"};function g(u,t,f,x,L,T){const e=l("Link");return p(),a("div",null,[t[11]||(t[11]=d('<h1 id="linux-服务器管理员的12个有用的命令" tabindex="-1">Linux 服务器管理员的12个有用的命令 <a class="header-anchor" href="#linux-服务器管理员的12个有用的命令" aria-label="Permalink to “Linux 服务器管理员的12个有用的命令”">​</a></h1><p>我们已经读了很多教程和看了很多视频了，你现在是一名Linux高级用户了。好的，恭喜你。但是还有一些需要学习！下面一些命令在你成为全能的管理员时会派上用场！</p><p><img src="http://www.efytimes.com/admin/useradmin/photo/fQjv122633PM162014.png" alt=""></p><ol><li><p><strong>ifconfig</strong>: 在修改内核中已有的网络接口时，你会用到ifconfig命令。这个命令通常用于系统调校和调试，但同时也可以用于在启动过程中设置接口。</p></li><li><p><strong>netstat</strong>: 对于Linux用户来说这是一个用于显示网络相关信息的高级命令。它包括路由表、网络连接、伪装连接、接口统计等丰富信息。</p></li><li><p><strong>nslookup</strong>: 在你需要找出关于网络服务的信息时可以用到这个命令。它能帮你找到用于查询DNS域的名称服务器信息。</p></li><li><p><strong>dig</strong>: dig工具用于请求DNS域名服务器。如果你要找出主机地址、邮件交换、名称服务器和其他相关信息，那么这个工具就是最佳选择。你可以在Linux和Mac OS X操作系统上使用这个命令。</p></li><li><p><strong>uptime</strong>: uptime命令用于验证服务器在无人照看下发生了什么。当你需要坐在服务器前查找错误的时候，这个命令尤其有用。</p></li><li><p><strong>wall</strong>: 这个命令用于给所有已登录的用户发送消息。你可以只给那些消息权限设置成了&#39;是&#39;的用户发消息。消息是作为wall命令的参数给出的。</p></li><li><p><strong>mesg</strong>: 用户可以使用&#39;write&#39;命令给你发送消息。但是作为服务器管理员，你可以使用mesg命令来决定他们是否能够使用write命令。你可以选择&#39;n&#39;和&#39;y&#39;，分别用于控制在屏幕上不弹出或者弹出消息。</p></li><li><p><strong>write</strong>: 如果对于一个用户的&#39;mesg&#39;命令的状态设置为&#39;y&#39;，那么write命令就允许你发送消息给那个用户。</p></li><li><p><strong>talk</strong>: 当上面所说的“消息”不够用时，使用talk命令与登陆的用户进行“会话”。</p></li><li><p><strong>w</strong>: 这个命令是uptime和who命令的结合，其显示结果就好像连续先后执行了这两个命令一样。</p></li><li><p><strong>rename</strong>:当你需要重命名特定的文件时，rename命令会派上用场。这个命令可以通过匹配替换来为多个文件批量重命名。</p></li><li><p><strong>top</strong>:这个命令可以显示运行在CPU上的进程。命令会自动刷新并持续显示进程直到你使用中断命令停止它。</p></li></ol><hr>',5)),o("p",null,[t[1]||(t[1]=n("via: ",-1)),i(e,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=125990"},{default:s(()=>[...t[0]||(t[0]=[n("http://www.efytimes.com/e1/fullnews.asp?edid=125990",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=n("译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[2]||(t[2]=[n("geekpi",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),i(e,{href:"http://blog.csdn.net/tinyeyeser"},{default:s(()=>[...t[3]||(t[3]=[n("Mr小眼儿",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const v=r(m,[["render",g]]);export{_ as __pageData,v as default};
